import { describe, expect, it } from "vitest";
import { ALL_TOOL_CONTRACTS, cancelTracePlan, getTracePlan, listTracePlans, saveTracePlan, TOOL_NAMES, toolConfig, } from "./mcpContract.js";
describe("tool contracts", () => {
    it("registers 44 tools with unique names", () => {
        expect(ALL_TOOL_CONTRACTS).toHaveLength(44);
        expect(new Set(TOOL_NAMES).size).toBe(44);
        expect(TOOL_NAMES).toContain("save_trace_plan");
        expect(TOOL_NAMES).not.toContain("create_trace_plan");
        expect(TOOL_NAMES).not.toContain("update_trace_plan");
    });
    it("names every tool in snake_case", () => {
        for (const contract of ALL_TOOL_CONTRACTS) {
            expect(contract.name, contract.name).toMatch(/^[a-z][a-z0-9]*(_[a-z0-9]+)*$/);
        }
    });
    it("gives every tool a title and a description", () => {
        for (const contract of ALL_TOOL_CONTRACTS) {
            expect(contract.title.length, contract.name).toBeGreaterThan(0);
            expect(contract.description.length, contract.name).toBeGreaterThan(0);
        }
    });
    it("names every input parameter in camelCase", () => {
        for (const contract of ALL_TOOL_CONTRACTS) {
            for (const param of Object.keys(contract.inputSchema)) {
                expect(param, `${contract.name}.${param}`).toMatch(/^[a-z][a-zA-Z0-9]*$/);
            }
        }
    });
    it("describes every input parameter", () => {
        for (const contract of ALL_TOOL_CONTRACTS) {
            for (const [param, schema] of Object.entries(contract.inputSchema)) {
                // agentRunId is an internal bridge the analyze-repo flow injects, never
                // something the agent chooses, so it deliberately carries no prose.
                if (contract.name === "save_trace_plan" && param === "agentRunId") {
                    continue;
                }
                expect(schema.description, `${contract.name}.${param} has no .describe()`).toBeTruthy();
            }
        }
    });
    it("drops the name from the registerTool config", () => {
        const config = toolConfig(ALL_TOOL_CONTRACTS[0]);
        expect(config).not.toHaveProperty("name");
        expect(Object.keys(config).sort()).toEqual([
            "description",
            "inputSchema",
            "title",
        ]);
    });
    it("requires Modify callers to reconcile stored trace plans with current code", () => {
        expect(getTracePlan.description).toMatch(/historical intent/);
        expect(getTracePlan.description).toMatch(/reconcile.*current code/);
        expect(getTracePlan.description).toMatch(/never assume.*current instrumentation/);
        expect(getTracePlan.description).not.toMatch(/don't have to re-derive it from the code/);
    });
    it("allows structural updates to replace the trace-plan root", () => {
        expect(saveTracePlan.description).toMatch(/structural replacement may change `tree\.rootId`/);
    });
    it("lets callers find the existing plan for a trace function key", () => {
        expect(listTracePlans.inputSchema).toHaveProperty("traceFunctionKey");
        expect(listTracePlans.description).toMatch(/instead of creating a competing/);
    });
    it("warns that a key lookup misses unconfirmed plans", () => {
        // The tool layer has to carry this on its own: an agent outside the setup
        // flow reads "no plan for this key" and creates a rival otherwise.
        for (const description of [
            getTracePlan.description,
            saveTracePlan.description,
        ]) {
            expect(description).toMatch(/only for confirmed plans|\*confirmed\*/);
            expect(description).toMatch(/list_trace_plans\({ traceFunctionKey/);
        }
    });
    it("says which plan states a save can and cannot land on", () => {
        expect(saveTracePlan.description).toMatch(/cancelled plan is the one thing you cannot save onto/);
        expect(saveTracePlan.description).toMatch(/saving it revives it/);
    });
    it("points a wrong-but-wanted draft at save_trace_plan rather than cancel", () => {
        expect(cancelTracePlan.description).toMatch(/only an awaiting plan/i);
        expect(cancelTracePlan.description).toMatch(/update it with save_trace_plan/);
    });
});
